import { catchAsync } from "utils/catchAsync";
import FriendsReq from "models/friendRequest.model";
import User from "models/user.model";
import httpStatus from "http-status";
import ApiError from "utils/ApiError";

export const fetchAllFriends = catchAsync(async (req, res) => {
  const { no_of_data_each_page, current_page_number } = req.body;
  const userId = req.user._id;

  // Step 1: Match friends based on the userId
  const fetchFriends = await FriendsReq.aggregate([
    {
      $match: {
        $or: [
          { senderID: userId, status: "Accept" },
          { receiverID: userId, status: "Accept" },
        ],
      },
    },
    { $skip: no_of_data_each_page * current_page_number },
    { $limit: no_of_data_each_page },
  ]);

  // Step 2: Use for...of to get user details
  const friendDetails = [];

  for (const friend of fetchFriends) {
    if (friend.senderID.equals(userId)) {
      const populatedFriend = await FriendsReq.populate(friend, {
        path: "receiverID",
      });
      friend.friendInfo = populatedFriend.receiverID;
      friend.receiverID = populatedFriend.friendInfo._id;
      friendDetails.push(populatedFriend);
    } else {
      const populatedFriend = await FriendsReq.populate(friend, {
        path: "senderID",
      });
      friend.friendInfo = populatedFriend.senderID;
      friend.senderID = populatedFriend.friendInfo._id;
      friendDetails.push(populatedFriend);
    }
  }

  // Step 3: Check if no friends were found
  if (friendDetails.length === 0) {
    return res.status(httpStatus.OK).send({
      results: { success: false, message: "No Requests Found on This Page" },
    });
  }

  // Step 4: Send the response
  res.status(httpStatus.OK).send({ results: { success: true, friendDetails } });
});

export const sendFriendRequest = catchAsync(async (req, res) => {
  // send friend request logic here
  const { receiverID } = req.body;

  if (receiverID === req.user._id) {
    throw new ApiError(
      httpStatus.NOT_FOUND,
      "You Cannot Send Friend Request To Self"
    );
  }

  // 1. Check user is there in DB or not.
  const receiver = await User.findById(receiverID);
  if (!receiver) {
    throw new ApiError(
      httpStatus.NOT_FOUND,
      "The user you are trying to reach does not exist!"
    );
  }
  // 2. Check Friend Request Connection is Already there in Reciver User Account.
  const fetchFriendReq = await FriendsReq.findOne({
    $or: [
      { senderID: req.user._id, receiverID },
      { senderID: receiverID, receiverID: req.user._id },
    ],
  });
  if (fetchFriendReq) {
    if (fetchFriendReq?.status === "Pending") {
      throw new ApiError(
        httpStatus.NOT_FOUND,
        "A friend request is already pending!"
      );
    } else if (fetchFriendReq?.status === "Accept") {
      throw new ApiError(
        httpStatus.NOT_FOUND,
        "You are already friends with this user!"
      );
    } else if (fetchFriendReq?.status === "Blocked") {
      throw new ApiError(
        httpStatus.NOT_FOUND,
        "You have been blocked by this user."
      );
    }
  }
  const body = {
    senderID: req.user._id,
    receiverID: receiverID,
    status: "Pending",
  };
  // 3. Create Friend Request Into DB after clear all stage of validation.
  const friendReq = await FriendsReq.create(body);
  res.status(httpStatus.OK).send({ results: { success: true, friendReq } });
});

export const friendRequest = catchAsync(async (req, res) => {
  // 1. Check Friend Request is Available or Not By ID.
  const fetchFriendReq = await FriendsReq.findOne({ _id: req.params.id });
  if (!fetchFriendReq) {
    throw new ApiError(
      httpStatus.NOT_FOUND,
      "The requested friend request does not exist!"
    );
  }
  // 2. Check The Status of Friend Request if it was Already Accept or Not.
  if (fetchFriendReq.status === "Accept") {
    throw new ApiError(
      httpStatus.NOT_FOUND,
      "You are already friends with this user!"
    );
  }
  // 3. If Accept Then Update The Friend Request Status and If Reject then Delete the Friend Request From DB.
  if (req.body.status === "Accept") {
    const user = await FriendsReq.findOneAndUpdate(
      { _id: req.params.id },
      { $set: { status: req.body.status } },
      { new: true }
    );
    res.status(httpStatus.OK).send({ results: { success: true, user } });
  } else if (req.body.status === "Reject") {
    const user = await FriendsReq.findOneAndDelete({
      _id: req.params.id,
    });
    res.status(httpStatus.OK).send({
      results: {
        success: true,
        message: "Friend request rejected successfully.",
      },
    });
  }
});

export const getFriendRequestWithPagination = catchAsync(async (req, res) => {
  // paginate api logic
  const { no_of_data_each_page, current_page_number } = req.body;
  const userId = req.user._id;
  // 1. Check Friend Request is Available or Not for particular ReciverID.
  // 2. Check The Limit and Pagination For Friend Request if it was Valid then show the requests and If not then show ‘No Requests Found in This page’.
  const fetchFriendsRequests = await FriendsReq.aggregate([
    { $match: { receiverID: userId, status: "Pending" } },
    { $skip: no_of_data_each_page * current_page_number },
    { $limit: no_of_data_each_page },
  ]);

  const populatedFriendsRequests = await FriendsReq.populate(fetchFriendsRequests, {
    path: "senderID",
  });

  res
    .status(httpStatus.OK)
    .send({ results: { success: true, populatedFriendsRequests } });
});
